insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Quantitative Aptitude','Permutation & Combination','mcq','easy','In how many ways can 3 books be chosen from 8 different books if 2 particular books must always be among those chosen?','8 अलग-अलग पुस्तकों में से 3 पुस्तकें कितने तरीक़ों से चुनी जा सकती हैं, यदि 2 विशेष पुस्तकें चुनी गई पुस्तकों में हमेशा हों?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s07", "csat_order": 1}'::jsonb,'[{"id": "a", "body": "3", "body_hi": "3", "isCorrect": false}, {"id": "b", "body": "6", "body_hi": "6", "isCorrect": true}, {"id": "c", "body": "20", "body_hi": "20", "isCorrect": false}, {"id": "d", "body": "56", "body_hi": "56", "isCorrect": false}]'::jsonb,2.5,0.83,'With the 2 particular books already in, only the third book is left to choose, from the other 6: 6 ways. 56 = 8C3 ignores the condition; 20 = 6C3 chooses all three from the other six; 3 has no basis.','2 विशेष पुस्तकें पहले से शामिल होने पर केवल तीसरी पुस्तक चुननी है, बाक़ी 6 में से: 6 तरीक़े। 56 = 8C3 शर्त को अनदेखा करता है; 20 = 6C3 तीनों को बाक़ी छह में से चुनता है; 3 का कोई आधार नहीं।','csat-l4-s07-qa-pc-books-chosen-with-two-fixed','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','medium','The speeds of a car and a bus are in the ratio 4 : 3. If the bus went 15 km/h faster, the two would travel at the same speed. What is the car''s speed?','एक कार और एक बस की चालें 4 : 3 के अनुपात में हैं। यदि बस 15 किमी/घंटा तेज़ चलती, तो दोनों एक ही चाल से चलते। कार की चाल क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s07", "csat_order": 2}'::jsonb,'[{"id": "a", "body": "15 km/h", "body_hi": "15 किमी/घंटा", "isCorrect": false}, {"id": "b", "body": "30 km/h", "body_hi": "30 किमी/घंटा", "isCorrect": false}, {"id": "c", "body": "45 km/h", "body_hi": "45 किमी/घंटा", "isCorrect": false}, {"id": "d", "body": "60 km/h", "body_hi": "60 किमी/घंटा", "isCorrect": true}]'::jsonb,2.5,0.83,'Let the speeds be 4k and 3k. The extra 15 km/h closes the gap of one part, so k = 15: the car goes at 4 × 15 = 60 km/h and the bus at 45 km/h. 45 km/h is the bus''s speed; 15 km/h is the size of one part; 30 km/h has no basis.','चालें 4k और 3k मानिए। अतिरिक्त 15 किमी/घंटा एक भाग का अंतर पाट देता है, इसलिए k = 15: कार 4 × 15 = 60 किमी/घंटा से और बस 45 किमी/घंटा से चलती है। 45 किमी/घंटा बस की चाल है; 15 किमी/घंटा एक भाग का आकार है; 30 किमी/घंटा का कोई आधार नहीं।','csat-l4-s07-qa-sdt-speeds-whose-ratio-changes','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Geometry & Mensuration','mcq','medium','A bowl is in the shape of a hemisphere with an inner radius of 21 cm. How many litres does it hold when full? (Take π = 22/7.)','एक कटोरा 21 सेमी भीतरी त्रिज्या वाले अर्धगोले के आकार का है। भरा होने पर उसमें कितने लीटर आते हैं? (π = 22/7 लीजिए।)','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s07", "csat_order": 3}'::jsonb,'[{"id": "a", "body": "9.702 litres", "body_hi": "9.702 लीटर", "isCorrect": false}, {"id": "b", "body": "19.404 litres", "body_hi": "19.404 लीटर", "isCorrect": true}, {"id": "c", "body": "38.808 litres", "body_hi": "38.808 लीटर", "isCorrect": false}, {"id": "d", "body": "58.212 litres", "body_hi": "58.212 लीटर", "isCorrect": false}]'::jsonb,2.5,0.83,'A hemisphere holds half of a sphere: ½ × 4/3 × πr³ = 2/3 × 22/7 × 21 × 21 × 21 = 19,404 cubic centimetres. A litre is 1,000 cubic centimetres, so the bowl holds 19.404 litres. 38.808 litres is the whole sphere; 9.702 litres halves the hemisphere again; 58.212 litres has no basis.','अर्धगोला एक गोले का आधा रखता है: ½ × 4/3 × πr³ = 2/3 × 22/7 × 21 × 21 × 21 = 19,404 घन सेमी। एक लीटर 1,000 घन सेमी है, इसलिए कटोरे में 19.404 लीटर आते हैं। 38.808 लीटर पूरा गोला है; 9.702 लीटर अर्धगोले को फिर आधा करता है; 58.212 लीटर का कोई आधार नहीं।','csat-l4-s07-qa-gm-the-litres-in-a-hemispherical-bowl','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Direction & Distance','mcq','medium','One evening Mohan walks 10 m straight towards the setting sun. He then turns to his left and walks 5 m, and turns to his left again and walks 10 m. In which direction is he now from where he started?','एक शाम मोहन डूबते सूरज की ओर सीधे 10 मीटर चलता है। फिर वह अपनी बाईं ओर मुड़कर 5 मीटर चलता है, और फिर बाईं ओर मुड़कर 10 मीटर चलता है। अब वह अपने आरंभ स्थान से किस दिशा में है?','{"craft": "inference", "csat_set": "csat-l4-s07", "csat_order": 4}'::jsonb,'[{"id": "a", "body": "South", "body_hi": "दक्षिण", "isCorrect": true}, {"id": "b", "body": "North", "body_hi": "उत्तर", "isCorrect": false}, {"id": "c", "body": "East", "body_hi": "पूर्व", "isCorrect": false}, {"id": "d", "body": "West", "body_hi": "पश्चिम", "isCorrect": false}]'::jsonb,2.5,0.83,'The setting sun is in the west, so Mohan first walks 10 m west. A left turn from west faces south, so he walks 5 m south; another left turn faces east, and the 10 m east cancels the first 10 m west. He ends 5 m due south of his start. North would follow from right turns instead of left; west and east forget that the two 10 m legs cancel.','डूबता सूरज पश्चिम में होता है, इसलिए मोहन पहले 10 मीटर पश्चिम चलता है। पश्चिम से बाईं ओर मुड़ने पर मुख दक्षिण होता है, इसलिए वह 5 मीटर दक्षिण चलता है; फिर बाईं ओर मुड़ने पर मुख पूर्व होता है, और 10 मीटर पूर्व पहले के 10 मीटर पश्चिम को काट देता है। वह अपने आरंभ से 5 मीटर ठीक दक्षिण में पहुँचता है। उत्तर बाएँ के बजाय दाएँ मुड़ने से आता; पश्चिम और पूर्व यह भूल जाते हैं कि 10-10 मीटर के दोनों चरण एक-दूसरे को काट देते हैं।','csat-l4-s07-lr-dd-a-walk-that-begins-towards-the-evening-sun','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','hard','What is the largest whole number n for which n! (the product 1 × 2 × ... × n) is less than 10,00,000?','वह सबसे बड़ी पूर्ण संख्या n कौन-सी है जिसके लिए n! (गुणनफल 1 × 2 × ... × n) 10,00,000 से कम है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s07", "csat_order": 5}'::jsonb,'[{"id": "a", "body": "7", "body_hi": "7", "isCorrect": false}, {"id": "b", "body": "8", "body_hi": "8", "isCorrect": false}, {"id": "c", "body": "9", "body_hi": "9", "isCorrect": true}, {"id": "d", "body": "10", "body_hi": "10", "isCorrect": false}]'::jsonb,2.5,0.83,'Build it up: 6! = 720, 7! = 5,040, 8! = 40,320, 9! = 3,62,880 -- still below 10,00,000 -- and 10! = 36,28,800, which is above. So n = 9. 10 overshoots, as 10! is more than 36 lakh; 8 and 7 stop a step or two early.','बढ़ाते जाइए: 6! = 720, 7! = 5,040, 8! = 40,320, 9! = 3,62,880 -- अब भी 10,00,000 से नीचे -- और 10! = 36,28,800, जो ऊपर है। अतः n = 9। 10 आगे निकल जाता है, क्योंकि 10!, 36 लाख से अधिक है; 8 और 7 एक या दो कदम पहले रुकते हैं।','csat-l4-s07-qa-nt-the-largest-factorial-below-ten-lakh','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1973 two psychologists, Amos Tversky and Daniel Kahneman, gave a name to a short cut that people use to judge how common something is: they ask themselves how easily examples come to mind. Usually this works, because things that happen often are easy to recall. But memory is swayed by more than frequency. Events that are vivid, recent or much reported come to mind more easily than dull, everyday ones of the same frequency. So after news of an air crash many people feel that flying is dangerous, though in most countries far more people die on the roads in a single week than in air crashes in a year. The short cut is not foolish; it fails in a predictable way, by giving too much weight to whatever is dramatic. Knowing this, a careful person checks a vivid impression against the numbers before acting on it.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1973 में मनोवैज्ञानिक एमॉस त्वेर्स्की और डेनियल काह्नमन ने एक ऐसे शॉर्टकट का वर्णन किया जिससे लोग आँकते हैं कि कोई बात कितनी आम है: वे स्वयं से पूछते हैं कि उदाहरण कितनी आसानी से याद आते हैं। प्रायः यह काम करता है, क्योंकि जो बातें अक्सर होती हैं वे आसानी से याद आती हैं। पर स्मृति केवल बारंबारता से प्रभावित नहीं होती। जो घटनाएँ सजीव, हाल की या बहुत चर्चित हों, वे उतनी ही बार होने वाली नीरस, रोज़मर्रा की घटनाओं से अधिक आसानी से याद आती हैं। इसलिए किसी विमान दुर्घटना की ख़बर के बाद बहुत-से लोगों को लगता है कि उड़ना ख़तरनाक है, यद्यपि अधिकांश देशों में एक ही सप्ताह में सड़कों पर उससे कहीं अधिक लोग मरते हैं जितने एक वर्ष में विमान दुर्घटनाओं में। यह शॉर्टकट मूर्खतापूर्ण नहीं; यह एक अनुमानित ढंग से विफल होता है, जो कुछ भी नाटकीय हो उसे बहुत अधिक भार देकर। यह जानते हुए एक सावधान व्यक्ति किसी सजीव धारणा पर कुछ करने से पहले उसे आँकड़ों से जाँचता है।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s07", "passage_group": "csat-l4-s07-p01", "csat_order": 6}'::jsonb,'[{"id": "a", "body": "People should never rely on what they remember when they judge how likely something is.", "body_hi": "किसी बात की संभावना आँकते समय लोगों को कभी अपनी स्मृति पर निर्भर नहीं रहना चाहिए।", "isCorrect": false}, {"id": "b", "body": "Flying is in truth more dangerous than travelling by road, as the news of crashes shows.", "body_hi": "उड़ना वास्तव में सड़क यात्रा से अधिक ख़तरनाक है, जैसा दुर्घटनाओं की ख़बरें दिखाती हैं।", "isCorrect": false}, {"id": "c", "body": "Judging by what comes to mind mostly works but overrates the vivid; check the numbers.", "body_hi": "याद आने से आँकना प्रायः काम करता है पर सजीव घटनाओं को बढ़ा देता है, इसलिए आँकड़े जाँचिए।", "isCorrect": true}, {"id": "d", "body": "Memory records events in exact proportion to how often they really happen in the world.", "body_hi": "स्मृति घटनाओं को ठीक उसी अनुपात में दर्ज करती है जितनी बार वे दुनिया में सचमुच होती हैं।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage describes judging frequency by ease of recall, says it usually works, and shows how it fails predictably by overweighting vivid events -- so impressions should be checked against numbers. It calls the short cut not foolish, so it does not reject it; it says it usually works, not that it is always wrong; and it does not say flying is more dangerous than driving.','परिच्छेद याद आने की सरलता से बारंबारता आँकने का वर्णन करता है, कहता है कि यह प्रायः काम करता है, और दिखाता है कि यह सजीव घटनाओं को अधिक भार देकर अनुमानित ढंग से कैसे विफल होता है -- इसलिए धारणाओं को आँकड़ों से जाँचना चाहिए। वह शॉर्टकट को मूर्खतापूर्ण नहीं कहता, इसलिए उसे ख़ारिज नहीं करता; वह कहता है कि यह प्रायः काम करता है, यह नहीं कि यह हमेशा ग़लत है; और वह यह नहीं कहता कि उड़ना गाड़ी चलाने से अधिक ख़तरनाक है।','csat-l4-s07-rc-p01-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1973 two psychologists, Amos Tversky and Daniel Kahneman, gave a name to a short cut that people use to judge how common something is: they ask themselves how easily examples come to mind. Usually this works, because things that happen often are easy to recall. But memory is swayed by more than frequency. Events that are vivid, recent or much reported come to mind more easily than dull, everyday ones of the same frequency. So after news of an air crash many people feel that flying is dangerous, though in most countries far more people die on the roads in a single week than in air crashes in a year. The short cut is not foolish; it fails in a predictable way, by giving too much weight to whatever is dramatic. Knowing this, a careful person checks a vivid impression against the numbers before acting on it.

Which one of the following would the passage''s reasoning most lead us to expect?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1973 में मनोवैज्ञानिक एमॉस त्वेर्स्की और डेनियल काह्नमन ने एक ऐसे शॉर्टकट का वर्णन किया जिससे लोग आँकते हैं कि कोई बात कितनी आम है: वे स्वयं से पूछते हैं कि उदाहरण कितनी आसानी से याद आते हैं। प्रायः यह काम करता है, क्योंकि जो बातें अक्सर होती हैं वे आसानी से याद आती हैं। पर स्मृति केवल बारंबारता से प्रभावित नहीं होती। जो घटनाएँ सजीव, हाल की या बहुत चर्चित हों, वे उतनी ही बार होने वाली नीरस, रोज़मर्रा की घटनाओं से अधिक आसानी से याद आती हैं। इसलिए किसी विमान दुर्घटना की ख़बर के बाद बहुत-से लोगों को लगता है कि उड़ना ख़तरनाक है, यद्यपि अधिकांश देशों में एक ही सप्ताह में सड़कों पर उससे कहीं अधिक लोग मरते हैं जितने एक वर्ष में विमान दुर्घटनाओं में। यह शॉर्टकट मूर्खतापूर्ण नहीं; यह एक अनुमानित ढंग से विफल होता है, जो कुछ भी नाटकीय हो उसे बहुत अधिक भार देकर। यह जानते हुए एक सावधान व्यक्ति किसी सजीव धारणा पर कुछ करने से पहले उसे आँकड़ों से जाँचता है।

परिच्छेद के तर्क के आधार पर निम्नलिखित में से किसकी सबसे अधिक अपेक्षा की जानी चाहिए?','{"craft": "inference", "csat_set": "csat-l4-s07", "passage_group": "csat-l4-s07-p01", "csat_order": 7}'::jsonb,'[{"id": "a", "body": "After weeks of news about a few shark attacks, people overrate the risk of a shark attack.", "body_hi": "कुछ शार्क हमलों की हफ़्तों की ख़बरों के बाद लोग शार्क के हमले के जोखिम को बढ़ाकर आँकते हैं।", "isCorrect": true}, {"id": "b", "body": "People who read a great deal of news judge the frequency of rare events more accurately than others.", "body_hi": "बहुत अधिक ख़बरें पढ़ने वाले लोग दुर्लभ घटनाओं की बारंबारता को दूसरों से अधिक सटीक आँकते हैं।", "isCorrect": false}, {"id": "c", "body": "Dramatic risks are usually underrated, because people prefer not to think about frightening events.", "body_hi": "नाटकीय जोखिम प्रायः कम आँके जाते हैं, क्योंकि लोग डरावनी घटनाओं के बारे में न सोचना पसंद करते हैं।", "isCorrect": false}, {"id": "d", "body": "Ordinary, everyday risks are the ones that people most often overrate when they think about danger.", "body_hi": "साधारण, रोज़मर्रा के जोखिम ही वे हैं जिन्हें लोग ख़तरे के बारे में सोचते समय सबसे अधिक बढ़ाकर आँकते हैं।", "isCorrect": false}]'::jsonb,2.5,0.83,'The short cut gives too much weight to what is vivid and much reported. After weeks of news about a few shark attacks, people would rate the risk of shark attacks higher than the facts justify, while dull and common risks, such as drowning in an ordinary pool, are underrated. The passage gives no reason to think people underrate dramatic risks, that news coverage makes judgements more accurate, or that common risks are the ones most often overrated.','शॉर्टकट सजीव और बहुत चर्चित बातों को बहुत अधिक भार देता है। कुछ शार्क हमलों की हफ़्तों की ख़बरों के बाद लोग शार्क हमले के जोखिम को तथ्यों से अधिक आँकेंगे, जबकि नीरस और आम जोखिम, जैसे किसी साधारण तालाब में डूबना, कम आँके जाते हैं। परिच्छेद यह मानने का कोई कारण नहीं देता कि लोग नाटकीय जोखिमों को कम आँकते हैं, कि ख़बरों से निर्णय अधिक सटीक होते हैं, या कि आम जोखिम ही सबसे अधिक बढ़ाकर आँके जाते हैं।','csat-l4-s07-rc-p01-what-the-reasoning-predicts','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1973 two psychologists, Amos Tversky and Daniel Kahneman, gave a name to a short cut that people use to judge how common something is: they ask themselves how easily examples come to mind. Usually this works, because things that happen often are easy to recall. But memory is swayed by more than frequency. Events that are vivid, recent or much reported come to mind more easily than dull, everyday ones of the same frequency. So after news of an air crash many people feel that flying is dangerous, though in most countries far more people die on the roads in a single week than in air crashes in a year. The short cut is not foolish; it fails in a predictable way, by giving too much weight to whatever is dramatic. Knowing this, a careful person checks a vivid impression against the numbers before acting on it.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1973 में मनोवैज्ञानिक एमॉस त्वेर्स्की और डेनियल काह्नमन ने एक ऐसे शॉर्टकट का वर्णन किया जिससे लोग आँकते हैं कि कोई बात कितनी आम है: वे स्वयं से पूछते हैं कि उदाहरण कितनी आसानी से याद आते हैं। प्रायः यह काम करता है, क्योंकि जो बातें अक्सर होती हैं वे आसानी से याद आती हैं। पर स्मृति केवल बारंबारता से प्रभावित नहीं होती। जो घटनाएँ सजीव, हाल की या बहुत चर्चित हों, वे उतनी ही बार होने वाली नीरस, रोज़मर्रा की घटनाओं से अधिक आसानी से याद आती हैं। इसलिए किसी विमान दुर्घटना की ख़बर के बाद बहुत-से लोगों को लगता है कि उड़ना ख़तरनाक है, यद्यपि अधिकांश देशों में एक ही सप्ताह में सड़कों पर उससे कहीं अधिक लोग मरते हैं जितने एक वर्ष में विमान दुर्घटनाओं में। यह शॉर्टकट मूर्खतापूर्ण नहीं; यह एक अनुमानित ढंग से विफल होता है, जो कुछ भी नाटकीय हो उसे बहुत अधिक भार देकर। यह जानते हुए एक सावधान व्यक्ति किसी सजीव धारणा पर कुछ करने से पहले उसे आँकड़ों से जाँचता है।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["Judging how common something is by how easily examples come to mind is usually wrong.", "The short cut misleads mainly when something is easy to recall for reasons other than how often it happens."], "statements_hi": ["उदाहरणों के आसानी से याद आने से किसी बात के आम होने का आकलन प्रायः ग़लत होता है।", "शॉर्टकट मुख्यतः तब भटकाता है जब कोई बात इसकी बारंबारता के अलावा अन्य कारणों से आसानी से याद आए।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s07", "passage_group": "csat-l4-s07-p01", "csat_order": 8}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 2 is valid. The passage says the short cut usually works because frequent things are easy to recall; it goes wrong when vividness, recency or reporting, rather than frequency, makes something easy to recall. 1 contradicts the passage, which says the short cut ''usually'' works and ''is not foolish''.','केवल 2 वैध है। परिच्छेद कहता है कि शॉर्टकट प्रायः इसलिए काम करता है कि बार-बार होने वाली बातें आसानी से याद आती हैं; वह तब ग़लत होता है जब बारंबारता के बजाय सजीवता, हाल का होना या चर्चा किसी बात को आसानी से याद आने लायक़ बनाती है। 1 परिच्छेद का खंडन करता है, जो कहता है कि शॉर्टकट ''प्रायः'' काम करता है और ''मूर्खतापूर्ण नहीं'' है।','csat-l4-s07-rc-p01-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Sequences & Series','mcq','hard','Three numbers in arithmetic progression add up to 15, and their product is 80. What is the largest of them?','समांतर श्रेणी में तीन संख्याओं का योग 15 है, और उनका गुणनफल 80 है। उनमें सबसे बड़ी कौन-सी है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s07", "csat_order": 9}'::jsonb,'[{"id": "a", "body": "2", "body_hi": "2", "isCorrect": false}, {"id": "b", "body": "5", "body_hi": "5", "isCorrect": false}, {"id": "c", "body": "8", "body_hi": "8", "isCorrect": true}, {"id": "d", "body": "11", "body_hi": "11", "isCorrect": false}]'::jsonb,2.5,0.83,'Write the numbers as 5 - d, 5 and 5 + d, since three numbers in AP adding to 15 have 5 in the middle. Their product is 5(25 - d²) = 80, so 25 - d² = 16 and d = 3: the numbers are 2, 5 and 8. The largest is 8. 5 is the middle number; 2 is the smallest; 11 adds the difference twice.','संख्याओं को 5 - d, 5 और 5 + d लिखिए, क्योंकि 15 योग वाली समांतर श्रेणी की तीन संख्याओं के बीच में 5 होता है। उनका गुणनफल 5(25 - d²) = 80 है, इसलिए 25 - d² = 16 और d = 3: संख्याएँ 2, 5 और 8 हैं। सबसे बड़ी 8 है। 5 बीच की संख्या है; 2 सबसे छोटी; 11 अंतर को दो बार जोड़ता है।','csat-l4-s07-qa-ss-three-numbers-in-ap-from-their-sum-and-product','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Permutation & Combination','mcq','hard','A family has two children, and it is known that at least one of them is a girl. If each child is equally likely to be a boy or a girl, what is the probability that both are girls?','एक परिवार में दो बच्चे हैं, और यह ज्ञात है कि उनमें से कम से कम एक लड़की है। यदि हर बच्चे के लड़का या लड़की होने की संभावना बराबर हो, तो दोनों के लड़कियाँ होने की प्रायिकता क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s07", "csat_order": 10}'::jsonb,'[{"id": "a", "body": "1/4", "body_hi": "1/4", "isCorrect": false}, {"id": "b", "body": "1/3", "body_hi": "1/3", "isCorrect": true}, {"id": "c", "body": "1/2", "body_hi": "1/2", "isCorrect": false}, {"id": "d", "body": "2/3", "body_hi": "2/3", "isCorrect": false}]'::jsonb,2.5,0.83,'Two children can be, in order of birth, boy-boy, boy-girl, girl-boy or girl-girl, all equally likely. ''At least one girl'' rules out only boy-boy, leaving three cases, of which one is girl-girl: 1/3. 1/2 treats the other child as a separate coin toss, but we are not told which child is the girl; 1/4 ignores the information given; 2/3 is the chance that the family has one boy and one girl.','दो बच्चे, जन्म के क्रम में, लड़का-लड़का, लड़का-लड़की, लड़की-लड़का या लड़की-लड़की हो सकते हैं, सब समान संभावित। ''कम से कम एक लड़की'' केवल लड़का-लड़का को ख़ारिज करता है, जिससे तीन स्थितियाँ बचती हैं, जिनमें एक लड़की-लड़की है: 1/3। 1/2 दूसरे बच्चे को एक अलग सिक्का-उछाल मानता है, पर यह नहीं बताया गया कि कौन-सा बच्चा लड़की है; 1/4 दी गई जानकारी को अनदेखा करता है; 2/3 परिवार में एक लड़का और एक लड़की होने की संभावना है।','csat-l4-s07-qa-pc-two-girls-given-at-least-one','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Blood Relation','mcq','medium','Pointing to a woman, Ravi says, ''She is my son''s wife''s mother-in-law.'' Ravi has only one son. How is the woman related to Ravi?','एक महिला की ओर संकेत करते हुए रवि कहता है, ''यह मेरे बेटे की पत्नी की सास है।'' रवि का केवल एक बेटा है। वह महिला रवि की क्या लगती है?','{"craft": "inference", "csat_set": "csat-l4-s07", "csat_order": 11}'::jsonb,'[{"id": "a", "body": "His mother", "body_hi": "उसकी माँ", "isCorrect": false}, {"id": "b", "body": "His wife", "body_hi": "उसकी पत्नी", "isCorrect": true}, {"id": "c", "body": "His sister", "body_hi": "उसकी बहन", "isCorrect": false}, {"id": "d", "body": "His daughter-in-law", "body_hi": "उसकी पुत्रवधू (बहू)", "isCorrect": false}]'::jsonb,2.5,0.83,'A woman''s mother-in-law is her husband''s mother. Ravi''s son''s wife''s husband is Ravi''s son, and the son''s mother is Ravi''s wife. So the woman is Ravi''s wife. His mother would be the son''s grandmother; his sister would be the son''s aunt; and his daughter-in-law is the son''s wife herself, not her mother-in-law.','किसी स्त्री की सास उसके पति की माँ होती है। रवि के बेटे की पत्नी का पति रवि का बेटा है, और बेटे की माँ रवि की पत्नी है। अतः वह महिला रवि की पत्नी है। उसकी माँ बेटे की दादी होती; उसकी बहन बेटे की बुआ होती; और उसकी बहू स्वयं बेटे की पत्नी है, उसकी सास नहीं।','csat-l4-s07-lr-br-a-son-s-wife-s-mother-in-law','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','easy','Boxes on a factory''s conveyor belt are placed 1.5 m apart, and 40 of them pass a checking point every minute. How fast is the belt moving?','एक कारख़ाने की कन्वेयर बेल्ट पर डिब्बे 1.5 मीटर की दूरी पर रखे हैं, और उनमें से 40 हर मिनट एक जाँच-बिंदु से गुज़रते हैं। बेल्ट कितनी तेज़ चल रही है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s07", "csat_order": 12}'::jsonb,'[{"id": "a", "body": "0.5 m/s", "body_hi": "0.5 मीटर/सेकंड", "isCorrect": false}, {"id": "b", "body": "0.67 m/s", "body_hi": "0.67 मीटर/सेकंड", "isCorrect": false}, {"id": "c", "body": "1 m/s", "body_hi": "1 मीटर/सेकंड", "isCorrect": true}, {"id": "d", "body": "1.5 m/s", "body_hi": "1.5 मीटर/सेकंड", "isCorrect": false}]'::jsonb,2.5,0.83,'Each box that passes carries 1.5 m of belt with it, so in a minute 40 × 1.5 = 60 m of belt goes by: 60 m a minute is 1 m a second. 0.67 m/s divides 40 by 60 and forgets the spacing; 1.5 m/s takes the spacing as the distance moved each second; 0.5 m/s has no basis.','हर गुज़रने वाला डिब्बा अपने साथ 1.5 मीटर बेल्ट ले जाता है, इसलिए एक मिनट में 40 × 1.5 = 60 मीटर बेल्ट गुज़रती है: एक मिनट में 60 मीटर यानी एक सेकंड में 1 मीटर। 0.67 मीटर/सेकंड, 40 को 60 से भाग देता है और दूरी को भूल जाता है; 1.5 मीटर/सेकंड दूरी को हर सेकंड तय दूरी मान लेता है; 0.5 मीटर/सेकंड का कोई आधार नहीं।','csat-l4-s07-qa-sdt-boxes-on-a-conveyor-belt','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','easy','A farmyard has only hens and goats. Together they have 30 heads and 100 legs. How many goats are there?','एक बाड़े में केवल मुर्गियाँ और बकरियाँ हैं। सबके मिलाकर 30 सिर और 100 पैर हैं। कितनी बकरियाँ हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s07", "csat_order": 13}'::jsonb,'[{"id": "a", "body": "10", "body_hi": "10", "isCorrect": false}, {"id": "b", "body": "15", "body_hi": "15", "isCorrect": false}, {"id": "c", "body": "20", "body_hi": "20", "isCorrect": true}, {"id": "d", "body": "25", "body_hi": "25", "isCorrect": false}]'::jsonb,2.5,0.83,'If all 30 were hens there would be 60 legs. Each goat adds 2 legs more than a hen, and there are 40 legs too many, so there are 40 ÷ 2 = 20 goats (and 10 hens): 80 + 20 = 100 legs. 10 is the number of hens; 25 divides 100 by 4, as if every animal were a goat; 15 splits the heads evenly.','यदि सभी 30 मुर्गियाँ होतीं तो 60 पैर होते। हर बकरी मुर्गी से 2 पैर अधिक जोड़ती है, और 40 पैर अधिक हैं, इसलिए 40 ÷ 2 = 20 बकरियाँ हैं (और 10 मुर्गियाँ): 80 + 20 = 100 पैर। 10 मुर्गियों की संख्या है; 25, 100 को 4 से भाग देता है, मानो हर पशु बकरी हो; 15 सिरों को बराबर बाँटता है।','csat-l4-s07-qa-ph-heads-and-legs','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Economists long used the lighthouse as the textbook case of a good that markets cannot supply. Once a light is shining, every passing ship can see it, and there is no way to charge a ship for looking; so each shipowner, the argument ran, would wait for someone else to pay, and no private lighthouse would ever be built. Only the state, through taxes, could provide one. In 1974 the economist Ronald Coase showed that the history did not fit the textbook. In Britain many lighthouses had been built and run privately, paid for by dues collected from ships when they called at nearby ports -- a place where payment could be enforced. The lesson is not that the state is never needed, but that a free-rider problem can sometimes be solved by tying the payment to something from which non-payers can be excluded.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
अर्थशास्त्री लंबे समय तक प्रकाशस्तंभ को ऐसी वस्तु के पाठ्यपुस्तकीय उदाहरण के रूप में लेते रहे जिसे बाज़ार नहीं दे सकता। एक बार प्रकाश जल जाए, तो पास से गुज़रने वाला हर जहाज़ उसे देख सकता है, और देखने के लिए जहाज़ से शुल्क लेने का कोई उपाय नहीं; इसलिए, तर्क था, हर जहाज़-मालिक किसी और के भुगतान की प्रतीक्षा करेगा, और कोई निजी प्रकाशस्तंभ कभी नहीं बनेगा। केवल राज्य, करों के माध्यम से, उसे दे सकता था। 1974 में अर्थशास्त्री रोनाल्ड कोस ने दिखाया कि इतिहास पाठ्यपुस्तक से मेल नहीं खाता। ब्रिटेन में कई प्रकाशस्तंभ निजी रूप से बनाए और चलाए गए थे, जिनका ख़र्च जहाज़ों से तब वसूले गए शुल्कों से चलता था जब वे पास के बंदरगाहों पर रुकते -- एक ऐसी जगह जहाँ भुगतान लागू कराया जा सकता था। सीख यह नहीं कि राज्य की कभी आवश्यकता नहीं, बल्कि यह कि मुफ़्तख़ोरी की समस्या कभी-कभी भुगतान को किसी ऐसी चीज़ से जोड़कर हल की जा सकती है जिससे भुगतान न करने वालों को रोका जा सके।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s07", "passage_group": "csat-l4-s07-p02", "csat_order": 14}'::jsonb,'[{"id": "a", "body": "The state is never needed to provide goods such as lighthouses, which markets supply well.", "body_hi": "प्रकाशस्तंभ जैसी वस्तुएँ देने के लिए राज्य की कभी आवश्यकता नहीं, बाज़ार उन्हें अच्छी तरह देता है।", "isCorrect": false}, {"id": "b", "body": "Every good that is shared by all can be sold privately if the price is set high enough.", "body_hi": "सबके साझा उपयोग की हर वस्तु निजी रूप से बेची जा सकती है यदि मूल्य पर्याप्त ऊँचा रखा जाए।", "isCorrect": false}, {"id": "c", "body": "No private lighthouse was ever built, exactly as the textbooks had always said.", "body_hi": "कोई निजी प्रकाशस्तंभ कभी नहीं बना, ठीक जैसा पाठ्यपुस्तकें हमेशा कहती थीं।", "isCorrect": false}, {"id": "d", "body": "Free riding may be curbed by tying payment to something non-payers can be kept from.", "body_hi": "मुफ़्तख़ोरी की समस्या भुगतान को उस चीज़ से जोड़कर हल हो सकती है जिससे न चुकाने वाले रोके जा सकें।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage shows that the lighthouse, long cited as something only the state could provide, was in fact often provided privately by collecting dues at ports -- a way of tying payment to something from which non-payers could be excluded. It says the state is sometimes needed, so it does not say it never is; it does not say every public good can be sold privately; and it reports that private lighthouses existed, the opposite of none being built.','परिच्छेद दिखाता है कि प्रकाशस्तंभ, जिसे लंबे समय तक ऐसी चीज़ बताया गया जो केवल राज्य दे सकता है, वास्तव में प्रायः बंदरगाहों पर शुल्क वसूलकर निजी रूप से दिया गया -- भुगतान को ऐसी चीज़ से जोड़ने का उपाय जिससे भुगतान न करने वालों को रोका जा सके। वह कहता है कि राज्य की कभी-कभी आवश्यकता है, इसलिए यह नहीं कहता कि कभी नहीं; वह यह नहीं कहता कि हर सार्वजनिक वस्तु निजी रूप से बेची जा सकती है; और वह बताता है कि निजी प्रकाशस्तंभ थे, जो किसी के न बनने का उलटा है।','csat-l4-s07-rc-p02-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Economists long used the lighthouse as the textbook case of a good that markets cannot supply. Once a light is shining, every passing ship can see it, and there is no way to charge a ship for looking; so each shipowner, the argument ran, would wait for someone else to pay, and no private lighthouse would ever be built. Only the state, through taxes, could provide one. In 1974 the economist Ronald Coase showed that the history did not fit the textbook. In Britain many lighthouses had been built and run privately, paid for by dues collected from ships when they called at nearby ports -- a place where payment could be enforced. The lesson is not that the state is never needed, but that a free-rider problem can sometimes be solved by tying the payment to something from which non-payers can be excluded.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
अर्थशास्त्री लंबे समय तक प्रकाशस्तंभ को ऐसी वस्तु के पाठ्यपुस्तकीय उदाहरण के रूप में लेते रहे जिसे बाज़ार नहीं दे सकता। एक बार प्रकाश जल जाए, तो पास से गुज़रने वाला हर जहाज़ उसे देख सकता है, और देखने के लिए जहाज़ से शुल्क लेने का कोई उपाय नहीं; इसलिए, तर्क था, हर जहाज़-मालिक किसी और के भुगतान की प्रतीक्षा करेगा, और कोई निजी प्रकाशस्तंभ कभी नहीं बनेगा। केवल राज्य, करों के माध्यम से, उसे दे सकता था। 1974 में अर्थशास्त्री रोनाल्ड कोस ने दिखाया कि इतिहास पाठ्यपुस्तक से मेल नहीं खाता। ब्रिटेन में कई प्रकाशस्तंभ निजी रूप से बनाए और चलाए गए थे, जिनका ख़र्च जहाज़ों से तब वसूले गए शुल्कों से चलता था जब वे पास के बंदरगाहों पर रुकते -- एक ऐसी जगह जहाँ भुगतान लागू कराया जा सकता था। सीख यह नहीं कि राज्य की कभी आवश्यकता नहीं, बल्कि यह कि मुफ़्तख़ोरी की समस्या कभी-कभी भुगतान को किसी ऐसी चीज़ से जोड़कर हल की जा सकती है जिससे भुगतान न करने वालों को रोका जा सके।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["Privately run lighthouses in Britain were cheaper and better than those run by the state.", "The private owners found a way to charge each ship for seeing the light while it was at sea."], "statements_hi": ["ब्रिटेन में निजी रूप से चलाए गए प्रकाशस्तंभ राज्य द्वारा चलाए गए प्रकाशस्तंभों से सस्ते और बेहतर थे।", "निजी मालिकों ने हर जहाज़ से समुद्र में रहते हुए प्रकाश देखने का शुल्क लेने का उपाय खोज लिया।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s07", "passage_group": "csat-l4-s07-p02", "csat_order": 15}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": true}]'::jsonb,2.5,0.83,'Neither is valid. 1 goes too far: Coase showed that the history did not fit the textbook, but the passage does not say that private lighthouses were better run or cheaper than state ones. 2 reverses the passage''s point: the dues worked precisely because they were collected at ports, where a ship could be made to pay; the light itself still could not be charged for.','कोई भी वैध नहीं। 1 बहुत आगे जाता है: कोस ने दिखाया कि इतिहास पाठ्यपुस्तक से मेल नहीं खाता, पर परिच्छेद यह नहीं कहता कि निजी प्रकाशस्तंभ राज्य वालों से बेहतर चलाए गए या सस्ते थे। 2 परिच्छेद की बात को उलट देता है: शुल्क ठीक इसलिए काम करते थे कि वे बंदरगाहों पर वसूले जाते थे, जहाँ जहाज़ से भुगतान कराया जा सकता था; स्वयं प्रकाश के लिए अब भी शुल्क नहीं लिया जा सकता था।','csat-l4-s07-rc-p02-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Economists long used the lighthouse as the textbook case of a good that markets cannot supply. Once a light is shining, every passing ship can see it, and there is no way to charge a ship for looking; so each shipowner, the argument ran, would wait for someone else to pay, and no private lighthouse would ever be built. Only the state, through taxes, could provide one. In 1974 the economist Ronald Coase showed that the history did not fit the textbook. In Britain many lighthouses had been built and run privately, paid for by dues collected from ships when they called at nearby ports -- a place where payment could be enforced. The lesson is not that the state is never needed, but that a free-rider problem can sometimes be solved by tying the payment to something from which non-payers can be excluded.

Which one of the following uses the same kind of solution as the port dues described in the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
अर्थशास्त्री लंबे समय तक प्रकाशस्तंभ को ऐसी वस्तु के पाठ्यपुस्तकीय उदाहरण के रूप में लेते रहे जिसे बाज़ार नहीं दे सकता। एक बार प्रकाश जल जाए, तो पास से गुज़रने वाला हर जहाज़ उसे देख सकता है, और देखने के लिए जहाज़ से शुल्क लेने का कोई उपाय नहीं; इसलिए, तर्क था, हर जहाज़-मालिक किसी और के भुगतान की प्रतीक्षा करेगा, और कोई निजी प्रकाशस्तंभ कभी नहीं बनेगा। केवल राज्य, करों के माध्यम से, उसे दे सकता था। 1974 में अर्थशास्त्री रोनाल्ड कोस ने दिखाया कि इतिहास पाठ्यपुस्तक से मेल नहीं खाता। ब्रिटेन में कई प्रकाशस्तंभ निजी रूप से बनाए और चलाए गए थे, जिनका ख़र्च जहाज़ों से तब वसूले गए शुल्कों से चलता था जब वे पास के बंदरगाहों पर रुकते -- एक ऐसी जगह जहाँ भुगतान लागू कराया जा सकता था। सीख यह नहीं कि राज्य की कभी आवश्यकता नहीं, बल्कि यह कि मुफ़्तख़ोरी की समस्या कभी-कभी भुगतान को किसी ऐसी चीज़ से जोड़कर हल की जा सकती है जिससे भुगतान न करने वालों को रोका जा सके।

निम्नलिखित में से कौन-सा उसी प्रकार के हल का उपयोग करता है जैसा परिच्छेद में वर्णित बंदरगाह शुल्क?','{"craft": "inference", "csat_set": "csat-l4-s07", "passage_group": "csat-l4-s07-p02", "csat_order": 16}'::jsonb,'[{"id": "a", "body": "A town asks its residents to give whatever they wish, voluntarily, towards its street lights.", "body_hi": "एक नगर अपने निवासियों से सड़क-बत्तियों के लिए स्वेच्छा से जो चाहें देने को कहता है।", "isCorrect": false}, {"id": "b", "body": "A town pays for its street lights from a tax collected from every one of its residents.", "body_hi": "एक नगर अपनी सड़क-बत्तियों का ख़र्च अपने हर निवासी से वसूले गए कर से चलाता है।", "isCorrect": false}, {"id": "c", "body": "A market pays for the lights around it through a charge added to the fee for entering it.", "body_hi": "बाज़ार अपने आसपास की बत्तियों का ख़र्च प्रवेश-शुल्क में जोड़े प्रभार से चलाता है।", "isCorrect": true}, {"id": "d", "body": "A town switches off its street lights at midnight to save the cost of running them.", "body_hi": "एक नगर चलाने का ख़र्च बचाने के लिए आधी रात को अपनी सड़क-बत्तियाँ बुझा देता है।", "isCorrect": false}]'::jsonb,2.5,0.83,'The port dues worked by collecting payment at a point where non-payers could be excluded. A town that pays for its street lights through a charge added to the fee for entering its market does the same: the lights cannot be charged for directly, but entry to the market can. Asking residents for voluntary donations invites free riding; a tax on all residents is the state solution the passage contrasts with; and switching the lights off removes the good rather than paying for it.','बंदरगाह शुल्क ऐसे बिंदु पर भुगतान वसूलकर काम करते थे जहाँ भुगतान न करने वालों को रोका जा सके। जो नगर अपनी सड़क-बत्तियों का ख़र्च अपने बाज़ार में प्रवेश के शुल्क में जोड़े गए एक प्रभार से चलाए, वह यही करता है: बत्तियों के लिए सीधे शुल्क नहीं लिया जा सकता, पर बाज़ार में प्रवेश के लिए लिया जा सकता है। निवासियों से स्वैच्छिक दान माँगना मुफ़्तख़ोरी को न्योता देता है; सभी निवासियों पर कर वह राज्य वाला हल है जिससे परिच्छेद तुलना करता है; और बत्तियाँ बुझा देना वस्तु का ख़र्च चलाने के बजाय उसे ही हटा देता है।','csat-l4-s07-rc-p02-the-same-kind-of-solution','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','medium','x varies directly as y and inversely as z, and x = 6 when y = 4 and z = 2. What is x when y = 12 and z = 3?','x, y के अनुक्रमानुपाती और z के व्युत्क्रमानुपाती है, और y = 4 तथा z = 2 होने पर x = 6 है। y = 12 और z = 3 होने पर x क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s07", "csat_order": 17}'::jsonb,'[{"id": "a", "body": "4", "body_hi": "4", "isCorrect": false}, {"id": "b", "body": "6", "body_hi": "6", "isCorrect": false}, {"id": "c", "body": "8", "body_hi": "8", "isCorrect": false}, {"id": "d", "body": "12", "body_hi": "12", "isCorrect": true}]'::jsonb,2.5,0.83,'x = k × y/z, and 6 = k × 4/2 gives k = 3. Then x = 3 × 12/3 = 12. 6 leaves x unchanged; 4 multiplies by y/z without the constant 3 (12/3); 8 has no basis.','x = k × y/z, और 6 = k × 4/2 से k = 3 मिलता है। तब x = 3 × 12/3 = 12। 6, x को अपरिवर्तित छोड़ता है; 4, अचर 3 के बिना y/z (12/3) लेता है; 8 का कोई आधार नहीं।','csat-l4-s07-qa-rm-a-quantity-varying-with-two-others','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Coding-Decoding','mcq','hard','In a code, each letter of a word is replaced by its place when the letters of that word are arranged in alphabetical order, so that CAB, whose letters in order are A, B, C, becomes 312. How is LEMON written in this code?','एक कूट में किसी शब्द का हर अक्षर उस स्थान से बदला जाता है जो उसे उस शब्द के अक्षरों को वर्णानुक्रम में रखने पर मिलता है, ताकि CAB, जिसके अक्षर क्रम में A, B, C हैं, 312 बन जाए। इस कूट में LEMON कैसे लिखा जाता है?','{"craft": "inference", "csat_set": "csat-l4-s07", "csat_order": 18}'::jsonb,'[{"id": "a", "body": "12345", "body_hi": "12345", "isCorrect": false}, {"id": "b", "body": "21354", "body_hi": "21354", "isCorrect": true}, {"id": "c", "body": "21345", "body_hi": "21345", "isCorrect": false}, {"id": "d", "body": "31254", "body_hi": "31254", "isCorrect": false}]'::jsonb,2.5,0.83,'The letters of LEMON in alphabetical order are E, L, M, N, O, so E is 1st, L 2nd, M 3rd, N 4th and O 5th. Reading LEMON letter by letter: L 2, E 1, M 3, O 5, N 4 -- 21354. 12345 writes the ranks in alphabetical order rather than in the order of the word; 21345 swaps O and N; 31254 has no basis.','LEMON के अक्षर वर्णानुक्रम में E, L, M, N, O हैं, इसलिए E पहला, L दूसरा, M तीसरा, N चौथा और O पाँचवाँ है। LEMON को अक्षर-दर-अक्षर पढ़ने पर: L 2, E 1, M 3, O 5, N 4 -- 21354। 12345 स्थानों को शब्द के क्रम के बजाय वर्णानुक्रम में लिखता है; 21345, O और N को बदल देता है; 31254 का कोई आधार नहीं।','csat-l4-s07-lr-cd-each-letter-ranked-within-its-word','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','What is the last digit of the product of all the odd numbers from 1 to 99?','1 से 99 तक की सभी विषम संख्याओं के गुणनफल का अंतिम अंक क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s07", "csat_order": 19}'::jsonb,'[{"id": "a", "body": "0", "body_hi": "0", "isCorrect": false}, {"id": "b", "body": "1", "body_hi": "1", "isCorrect": false}, {"id": "c", "body": "3", "body_hi": "3", "isCorrect": false}, {"id": "d", "body": "5", "body_hi": "5", "isCorrect": true}]'::jsonb,2.5,0.83,'The product includes 5, so it is a multiple of 5, and since every factor is odd it is odd: an odd multiple of 5 always ends in 5. 0 would need a factor 2, and every factor here is odd; 1 comes from looking only at the last digits 1, 3, 7 and 9 and forgetting the multiples of 5; 3 has no basis.','गुणनफल में 5 शामिल है, इसलिए वह 5 का गुणज है, और चूँकि हर गुणनखंड विषम है, वह विषम है: 5 का विषम गुणज हमेशा 5 पर समाप्त होता है। 0 के लिए गुणनखंड 2 चाहिए, और यहाँ हर गुणनखंड विषम है; 1 केवल अंतिम अंकों 1, 3, 7 और 9 को देखने और 5 के गुणजों को भूलने से आता है; 3 का कोई आधार नहीं।','csat-l4-s07-qa-nt-the-last-digit-of-the-odd-numbers-multiplied','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','hard','On how many dates in 2027 does the day of the month multiplied by the number of the month give 27, the last two digits of the year (as on 9 March, 9 × 3 = 27)?','2027 की कितनी तारीख़ों पर महीने की तारीख़ को महीने की संख्या से गुणा करने पर 27 मिलता है, जो वर्ष के अंतिम दो अंक हैं (जैसे 9 मार्च को, 9 × 3 = 27)?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s07", "csat_order": 20}'::jsonb,'[{"id": "a", "body": "0", "body_hi": "0", "isCorrect": false}, {"id": "b", "body": "1", "body_hi": "1", "isCorrect": false}, {"id": "c", "body": "2", "body_hi": "2", "isCorrect": false}, {"id": "d", "body": "3", "body_hi": "3", "isCorrect": true}]'::jsonb,2.5,0.83,'27 = 1 × 27 = 3 × 9 = 9 × 3 = 27 × 1. The month must be 1 to 12, so the pairs that work are day 27 of month 1 (27 January), day 9 of month 3 (9 March) and day 3 of month 9 (3 September); day 1 of a 27th month does not exist. That is 3 dates. 2 misses one of the three -- usually 27 January; 1 counts only the example; 0 has no basis.','27 = 1 × 27 = 3 × 9 = 9 × 3 = 27 × 1। महीना 1 से 12 तक होना चाहिए, इसलिए चलने वाले जोड़े हैं महीने 1 की 27 तारीख़ (27 जनवरी), महीने 3 की 9 तारीख़ (9 मार्च) और महीने 9 की 3 तारीख़ (3 सितंबर); 27वें महीने की 1 तारीख़ होती ही नहीं। यानी 3 तारीख़ें। 2 तीन में से एक छोड़ देता है -- प्रायः 27 जनवरी; 1 केवल उदाहरण गिनता है; 0 का कोई आधार नहीं।','csat-l4-s07-qa-ph-dates-whose-day-times-month-is-27','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In The Spirit of the Laws, published in 1748, the French thinker Montesquieu argued that liberty is lost when the power to make laws, the power to carry them out and the power to judge are held by the same person or body; each must be able to check the others. Constitutions have applied the idea in different ways. The American Constitution keeps the President and the President''s secretaries out of the legislature altogether. India''s Constitution does not separate powers so sharply: under its parliamentary system, ministers are members of Parliament and remain in office only while they keep the support of the Lok Sabha. What India keeps is the idea of checks -- courts can strike down laws and executive acts that violate the Constitution, and Parliament can question and remove a government. The aim is not to keep the three powers apart for its own sake, but to ensure that none of them goes unchecked.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1748 में प्रकाशित ''द स्पिरिट ऑफ़ द लॉज़'' में फ़्रांसीसी विचारक मॉन्टेस्क्यू ने तर्क दिया कि स्वतंत्रता तब खो जाती है जब क़ानून बनाने, उन्हें लागू करने और न्याय करने की शक्तियाँ एक ही व्यक्ति या निकाय के पास हों; हर एक को दूसरों पर अंकुश रख पाना चाहिए। संविधानों ने इस विचार को अलग-अलग ढंग से लागू किया है। अमेरिकी संविधान राष्ट्रपति और राष्ट्रपति के सचिवों (मंत्रियों) को विधायिका से पूरी तरह बाहर रखता है। भारत का संविधान शक्तियों को इतनी कठोरता से अलग नहीं करता: उसकी संसदीय व्यवस्था में मंत्री संसद के सदस्य होते हैं और तभी तक पद पर रहते हैं जब तक उन्हें लोकसभा का समर्थन प्राप्त हो। भारत जो रखता है वह अंकुशों का विचार है -- न्यायालय संविधान का उल्लंघन करने वाले क़ानूनों और कार्यपालिका के कार्यों को रद्द कर सकते हैं, और संसद सरकार से प्रश्न पूछ सकती है और उसे हटा सकती है। उद्देश्य तीनों शक्तियों को केवल अलग रखना नहीं, बल्कि यह सुनिश्चित करना है कि कोई भी बिना अंकुश के न रहे।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s07", "passage_group": "csat-l4-s07-p03", "csat_order": 21}'::jsonb,'[{"id": "a", "body": "India''s Constitution separates the three powers exactly as the American one does.", "body_hi": "भारत का संविधान तीनों शक्तियों को ठीक वैसे ही अलग करता है जैसे अमेरिकी संविधान।", "isCorrect": false}, {"id": "b", "body": "No power should go unchecked, and India secures this without a strict separation.", "body_hi": "मायने यह रखता है कि कोई शक्ति बिना अंकुश के न रहे, जो भारत कठोर पृथक्करण के बिना सुनिश्चित करता है।", "isCorrect": true}, {"id": "c", "body": "In India the courts control Parliament, and Parliament has no check on the courts.", "body_hi": "भारत में न्यायालय संसद को नियंत्रित करते हैं, और संसद का न्यायालयों पर कोई अंकुश नहीं।", "isCorrect": false}, {"id": "d", "body": "Montesquieu held that liberty is safest when one body holds all the powers of the state.", "body_hi": "मॉन्टेस्क्यू का मत था कि स्वतंत्रता तब सबसे सुरक्षित है जब एक ही निकाय के पास राज्य की सभी शक्तियाँ हों।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage explains Montesquieu''s idea that combining the three powers endangers liberty, and shows that India keeps not a strict separation but the checks that stop any power going unchecked. It says India does not separate powers sharply, so it is not identical to the American model; it does not say the courts control Parliament; and it presents checks, not separation for its own sake, as the aim.','परिच्छेद मॉन्टेस्क्यू का यह विचार समझाता है कि तीनों शक्तियों को मिलाना स्वतंत्रता को ख़तरे में डालता है, और दिखाता है कि भारत कठोर पृथक्करण नहीं, बल्कि ऐसे अंकुश रखता है जो किसी शक्ति को बिना अंकुश के नहीं रहने देते। वह कहता है कि भारत शक्तियों को कठोरता से अलग नहीं करता, इसलिए वह अमेरिकी मॉडल जैसा नहीं; वह यह नहीं कहता कि न्यायालय संसद को नियंत्रित करते हैं; और वह पृथक्करण को अपने आप में नहीं, अंकुशों को उद्देश्य बताता है।','csat-l4-s07-rc-p03-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','easy','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In The Spirit of the Laws, published in 1748, the French thinker Montesquieu argued that liberty is lost when the power to make laws, the power to carry them out and the power to judge are held by the same person or body; each must be able to check the others. Constitutions have applied the idea in different ways. The American Constitution keeps the President and the President''s secretaries out of the legislature altogether. India''s Constitution does not separate powers so sharply: under its parliamentary system, ministers are members of Parliament and remain in office only while they keep the support of the Lok Sabha. What India keeps is the idea of checks -- courts can strike down laws and executive acts that violate the Constitution, and Parliament can question and remove a government. The aim is not to keep the three powers apart for its own sake, but to ensure that none of them goes unchecked.

According to the passage, how long do ministers in India remain in office?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1748 में प्रकाशित ''द स्पिरिट ऑफ़ द लॉज़'' में फ़्रांसीसी विचारक मॉन्टेस्क्यू ने तर्क दिया कि स्वतंत्रता तब खो जाती है जब क़ानून बनाने, उन्हें लागू करने और न्याय करने की शक्तियाँ एक ही व्यक्ति या निकाय के पास हों; हर एक को दूसरों पर अंकुश रख पाना चाहिए। संविधानों ने इस विचार को अलग-अलग ढंग से लागू किया है। अमेरिकी संविधान राष्ट्रपति और राष्ट्रपति के सचिवों (मंत्रियों) को विधायिका से पूरी तरह बाहर रखता है। भारत का संविधान शक्तियों को इतनी कठोरता से अलग नहीं करता: उसकी संसदीय व्यवस्था में मंत्री संसद के सदस्य होते हैं और तभी तक पद पर रहते हैं जब तक उन्हें लोकसभा का समर्थन प्राप्त हो। भारत जो रखता है वह अंकुशों का विचार है -- न्यायालय संविधान का उल्लंघन करने वाले क़ानूनों और कार्यपालिका के कार्यों को रद्द कर सकते हैं, और संसद सरकार से प्रश्न पूछ सकती है और उसे हटा सकती है। उद्देश्य तीनों शक्तियों को केवल अलग रखना नहीं, बल्कि यह सुनिश्चित करना है कि कोई भी बिना अंकुश के न रहे।

परिच्छेद के अनुसार, भारत में मंत्री कितने समय तक पद पर रहते हैं?','{"craft": "precision", "csat_set": "csat-l4-s07", "passage_group": "csat-l4-s07-p03", "csat_order": 22}'::jsonb,'[{"id": "a", "body": "For a fixed term of five years, whatever happens in Parliament", "body_hi": "संसद में चाहे जो हो, पाँच वर्ष की निश्चित अवधि तक", "isCorrect": false}, {"id": "b", "body": "For as long as the Supreme Court approves of their decisions", "body_hi": "जब तक सर्वोच्च न्यायालय उनके निर्णयों को स्वीकार करता है", "isCorrect": false}, {"id": "c", "body": "Only while they keep the support of the Lok Sabha", "body_hi": "केवल तब तक जब तक उन्हें लोकसभा का समर्थन प्राप्त है", "isCorrect": true}, {"id": "d", "body": "For as long as the President alone wishes, with no other check", "body_hi": "जब तक अकेले राष्ट्रपति चाहें, बिना किसी अन्य अंकुश के", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage says ministers ''remain in office only while they keep the support of the Lok Sabha''. It does not mention a fixed term, the President''s pleasure alone, or the approval of the Supreme Court.','परिच्छेद कहता है कि मंत्री ''तभी तक पद पर रहते हैं जब तक उन्हें लोकसभा का समर्थन प्राप्त हो''। वह किसी निश्चित अवधि, केवल राष्ट्रपति की इच्छा, या सर्वोच्च न्यायालय की स्वीकृति का उल्लेख नहीं करता।','csat-l4-s07-rc-p03-how-long-ministers-stay','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In The Spirit of the Laws, published in 1748, the French thinker Montesquieu argued that liberty is lost when the power to make laws, the power to carry them out and the power to judge are held by the same person or body; each must be able to check the others. Constitutions have applied the idea in different ways. The American Constitution keeps the President and the President''s secretaries out of the legislature altogether. India''s Constitution does not separate powers so sharply: under its parliamentary system, ministers are members of Parliament and remain in office only while they keep the support of the Lok Sabha. What India keeps is the idea of checks -- courts can strike down laws and executive acts that violate the Constitution, and Parliament can question and remove a government. The aim is not to keep the three powers apart for its own sake, but to ensure that none of them goes unchecked.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1748 में प्रकाशित ''द स्पिरिट ऑफ़ द लॉज़'' में फ़्रांसीसी विचारक मॉन्टेस्क्यू ने तर्क दिया कि स्वतंत्रता तब खो जाती है जब क़ानून बनाने, उन्हें लागू करने और न्याय करने की शक्तियाँ एक ही व्यक्ति या निकाय के पास हों; हर एक को दूसरों पर अंकुश रख पाना चाहिए। संविधानों ने इस विचार को अलग-अलग ढंग से लागू किया है। अमेरिकी संविधान राष्ट्रपति और राष्ट्रपति के सचिवों (मंत्रियों) को विधायिका से पूरी तरह बाहर रखता है। भारत का संविधान शक्तियों को इतनी कठोरता से अलग नहीं करता: उसकी संसदीय व्यवस्था में मंत्री संसद के सदस्य होते हैं और तभी तक पद पर रहते हैं जब तक उन्हें लोकसभा का समर्थन प्राप्त हो। भारत जो रखता है वह अंकुशों का विचार है -- न्यायालय संविधान का उल्लंघन करने वाले क़ानूनों और कार्यपालिका के कार्यों को रद्द कर सकते हैं, और संसद सरकार से प्रश्न पूछ सकती है और उसे हटा सकती है। उद्देश्य तीनों शक्तियों को केवल अलग रखना नहीं, बल्कि यह सुनिश्चित करना है कि कोई भी बिना अंकुश के न रहे।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["A system in which ministers sit in the legislature can still protect liberty if every power is checked.", "A branch of government kept wholly separate but answerable to no one would not meet the aim the passage describes."], "statements_hi": ["जिस व्यवस्था में मंत्री विधायिका में बैठते हैं, वह भी स्वतंत्रता की रक्षा कर सकती है यदि हर शक्ति पर अंकुश हो।", "सरकार की कोई शाखा जो पूरी तरह अलग रखी गई हो पर किसी के प्रति उत्तरदायी न हो, परिच्छेद में वर्णित उद्देश्य पूरा नहीं करेगी।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s07", "passage_group": "csat-l4-s07-p03", "csat_order": 23}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Both are valid. Montesquieu''s concern was that the same person or body might hold all three powers; India''s ministers belong to the legislature, yet the passage says India keeps checks on every power, so a system can join two powers and still guard liberty in his sense (1). And the passage says the aim is not to keep the powers apart ''for its own sake'' but to ensure none goes unchecked, so a perfectly separate power with no check on it would defeat that aim (2).','दोनों वैध हैं। मॉन्टेस्क्यू की चिंता यह थी कि एक ही व्यक्ति या निकाय के पास तीनों शक्तियाँ हों; भारत के मंत्री विधायिका के सदस्य हैं, फिर भी परिच्छेद कहता है कि भारत हर शक्ति पर अंकुश रखता है, इसलिए कोई व्यवस्था दो शक्तियों को जोड़कर भी उनके अर्थ में स्वतंत्रता की रक्षा कर सकती है (1)। और परिच्छेद कहता है कि उद्देश्य शक्तियों को ''केवल'' अलग रखना नहीं, बल्कि यह सुनिश्चित करना है कि कोई बिना अंकुश के न रहे, इसलिए पूरी तरह अलग पर बिना किसी अंकुश वाली शक्ति उस उद्देश्य को विफल करेगी (2)।','csat-l4-s07-rc-p03-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Geometry & Mensuration','mcq','easy','A rectangular plot 25 m long and 16 m wide is to be covered with turf costing ₹50 a square metre. What will the turf cost?','25 मीटर लंबे और 16 मीटर चौड़े एक आयताकार भूखंड पर ₹50 प्रति वर्ग मीटर की घास की परत (टर्फ़) बिछानी है। टर्फ़ पर कितना ख़र्च होगा?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s07", "csat_order": 24}'::jsonb,'[{"id": "a", "body": "₹2,050", "body_hi": "₹2,050", "isCorrect": false}, {"id": "b", "body": "₹4,100", "body_hi": "₹4,100", "isCorrect": false}, {"id": "c", "body": "₹20,000", "body_hi": "₹20,000", "isCorrect": true}, {"id": "d", "body": "₹40,000", "body_hi": "₹40,000", "isCorrect": false}]'::jsonb,2.5,0.83,'The plot''s area is 25 × 16 = 400 square metres, and 400 × ₹50 = ₹20,000. ₹4,100 prices the perimeter (82 m) instead of the area; ₹2,050 prices half the perimeter; ₹40,000 doubles the area.','भूखंड का क्षेत्रफल 25 × 16 = 400 वर्ग मीटर है, और 400 × ₹50 = ₹20,000। ₹4,100 क्षेत्रफल के बजाय परिमाप (82 मीटर) का मूल्य लगाता है; ₹2,050 आधे परिमाप का; ₹40,000 क्षेत्रफल को दोगुना करता है।','csat-l4-s07-qa-gm-turfing-a-plot','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Seating Arrangement','mcq','medium','Five flags -- red, blue, green, yellow and white -- hang one above another on a pole. The green flag is directly above the yellow one. Exactly one flag hangs between the blue flag and the red one. The blue flag is at the bottom. Which one of the following is correct?','पाँच झंडे -- लाल, नीला, हरा, पीला और सफ़ेद -- एक खंभे पर एक के ऊपर एक लटके हैं। हरा झंडा पीले के ठीक ऊपर है। नीले और लाल झंडे के बीच ठीक एक झंडा है। नीला झंडा सबसे नीचे है। निम्नलिखित में से कौन-सा सही है?','{"craft": "inference", "csat_set": "csat-l4-s07", "csat_order": 25}'::jsonb,'[{"id": "a", "body": "The red flag is at the top.", "body_hi": "लाल झंडा सबसे ऊपर है।", "isCorrect": false}, {"id": "b", "body": "The yellow flag is directly below the red one.", "body_hi": "पीला झंडा लाल झंडे के ठीक नीचे है।", "isCorrect": false}, {"id": "c", "body": "The green flag is in the middle.", "body_hi": "हरा झंडा बीच में है।", "isCorrect": false}, {"id": "d", "body": "The white flag is directly above the blue one.", "body_hi": "सफ़ेद झंडा नीले के ठीक ऊपर है।", "isCorrect": true}]'::jsonb,2.5,0.83,'Blue is 5th from the top, so red, with one flag between, is 3rd. Green and yellow must be next to each other with green above, and the only two neighbouring places left are the 1st and 2nd: green 1st, yellow 2nd. White takes the 4th place, directly above blue. Red is 3rd, not at the top; yellow is above red, not below it; and green is at the top, not in the middle.','नीला ऊपर से 5वाँ है, इसलिए लाल, बीच में एक झंडे के साथ, तीसरा है। हरा और पीला पड़ोसी होने चाहिए और हरा ऊपर, और बचे हुए एकमात्र पड़ोसी स्थान पहला और दूसरा हैं: हरा पहला, पीला दूसरा। सफ़ेद चौथा स्थान लेता है, नीले के ठीक ऊपर। लाल तीसरा है, सबसे ऊपर नहीं; पीला लाल के ऊपर है, नीचे नहीं; और हरा सबसे ऊपर है, बीच में नहीं।','csat-l4-s07-lr-sa-five-flags-on-a-pole','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','medium','Asha and Bina both walk the same 12 km route. Asha walks at 3 km/h and sets off at 8:00 a.m.; Bina walks at 4 km/h and sets off an hour later, at 9:00 a.m. Who arrives first?','आशा और बीना दोनों एक ही 12 किमी का रास्ता चलती हैं। आशा 3 किमी/घंटा से चलती है और सुबह 8:00 बजे निकलती है; बीना 4 किमी/घंटा से चलती है और एक घंटा बाद, सुबह 9:00 बजे, निकलती है। पहले कौन पहुँचती है?','{"craft": "inference", "csat_set": "csat-l4-s07", "csat_order": 26}'::jsonb,'[{"id": "a", "body": "They arrive at the same time.", "body_hi": "दोनों एक ही समय पहुँचती हैं।", "isCorrect": true}, {"id": "b", "body": "Asha arrives first, by a whole hour.", "body_hi": "आशा पूरे एक घंटे पहले पहुँचती है।", "isCorrect": false}, {"id": "c", "body": "Bina arrives first, by half an hour.", "body_hi": "बीना आधा घंटा पहले पहुँचती है।", "isCorrect": false}, {"id": "d", "body": "Bina arrives first, by a whole hour.", "body_hi": "बीना पूरे एक घंटे पहले पहुँचती है।", "isCorrect": false}]'::jsonb,2.5,0.83,'Asha takes 12 ÷ 3 = 4 hours and arrives at 12:00 noon. Bina takes 12 ÷ 4 = 3 hours, and starting at 9:00 she too arrives at 12:00 noon. They arrive together. Bina an hour early forgets her late start; Asha an hour early counts the late start but not Bina''s faster pace; Bina half an hour early has no basis.','आशा को 12 ÷ 3 = 4 घंटे लगते हैं और वह दोपहर 12:00 बजे पहुँचती है। बीना को 12 ÷ 4 = 3 घंटे लगते हैं, और 9:00 बजे चलकर वह भी दोपहर 12:00 बजे पहुँचती है। दोनों साथ पहुँचती हैं। बीना का एक घंटा पहले पहुँचना उसकी देर से शुरुआत भूल जाता है; आशा का एक घंटा पहले पहुँचना देर से शुरुआत गिनता है पर बीना की तेज़ चाल नहीं; बीना के आधा घंटा पहले पहुँचने का कोई आधार नहीं।','csat-l4-s07-qa-sdt-a-late-start-that-ends-in-a-tie','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','hard','How many of the whole numbers from 1 to 49 have no factor in common with 50 other than 1?','1 से 49 तक की कितनी पूर्ण संख्याओं का 50 के साथ 1 के अलावा कोई सार्व गुणनखंड नहीं है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s07", "csat_order": 27}'::jsonb,'[{"id": "a", "body": "20", "body_hi": "20", "isCorrect": true}, {"id": "b", "body": "25", "body_hi": "25", "isCorrect": false}, {"id": "c", "body": "30", "body_hi": "30", "isCorrect": false}, {"id": "d", "body": "40", "body_hi": "40", "isCorrect": false}]'::jsonb,2.5,0.83,'50 = 2 × 5², so a number shares a factor with 50 exactly when it is even or a multiple of 5. Of the 50 numbers from 1 to 50, half are even, leaving 25 odd ones, and of these the odd multiples of 5 (5, 15, 25, 35, 45) are 5 more to remove: 20 remain (50 itself is not among them). 25 counts all the odd numbers; 40 removes only the multiples of 5 (49 - 9); 30 has no basis.','50 = 2 × 5², इसलिए किसी संख्या का 50 से सार्व गुणनखंड ठीक तब होता है जब वह सम हो या 5 का गुणज। 1 से 50 तक की 50 संख्याओं में आधी सम हैं, जिससे 25 विषम बचती हैं, और इनमें 5 के विषम गुणज (5, 15, 25, 35, 45) 5 और हटाने हैं: 20 बचती हैं (स्वयं 50 उनमें नहीं)। 25 सभी विषम संख्याएँ गिनता है; 40 केवल 5 के गुणज हटाता है (49 - 9); 30 का कोई आधार नहीं।','csat-l4-s07-qa-nt-numbers-below-50-co-prime-to-50','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','hard','A car''s odometer reads 15951 km, a number that reads the same backwards. Exactly 2 hours later it shows the next such number. What was the car''s average speed?','एक कार का ओडोमीटर 15951 किमी दिखाता है, एक ऐसी संख्या जो उलटी पढ़ने पर भी वही रहती है। ठीक 2 घंटे बाद वह अगली ऐसी संख्या दिखाता है। कार की औसत चाल क्या थी?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s07", "csat_order": 28}'::jsonb,'[{"id": "a", "body": "50 km/h", "body_hi": "50 किमी/घंटा", "isCorrect": false}, {"id": "b", "body": "55 km/h", "body_hi": "55 किमी/घंटा", "isCorrect": true}, {"id": "c", "body": "60 km/h", "body_hi": "60 किमी/घंटा", "isCorrect": false}, {"id": "d", "body": "110 km/h", "body_hi": "110 किमी/घंटा", "isCorrect": false}]'::jsonb,2.5,0.83,'The next number reading the same backwards cannot keep 159 as its first three digits (15951 is the largest such), so it starts 160..., giving 16061. The car went 16061 - 15951 = 110 km in 2 hours: 55 km/h. 110 km/h forgets to divide by the 2 hours; 50 and 60 km/h have no basis.','उलटी पढ़ने पर वही रहने वाली अगली संख्या पहले तीन अंक 159 नहीं रख सकती (15951 ऐसी सबसे बड़ी है), इसलिए वह 160... से शुरू होती है, जिससे 16061 मिलता है। कार ने 2 घंटों में 16061 - 15951 = 110 किमी तय किए: 55 किमी/घंटा। 110 किमी/घंटा 2 घंटों से भाग देना भूल जाता है; 50 और 60 किमी/घंटा का कोई आधार नहीं।','csat-l4-s07-qa-ph-the-next-palindrome-on-an-odometer','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
The Constitution as adopted in 1950 listed citizens'' rights but said little about their duties. In 1976, on the recommendation of the Swaran Singh Committee, the Forty-second Amendment added Part IV-A, with a list of Fundamental Duties: among them, to abide by the Constitution and respect the national flag and anthem, to promote harmony among all the people of India, to protect the natural environment and to develop a scientific temper. An eleventh, the duty of parents to provide opportunities for education to their children aged six to fourteen, was added in 2002. Like the Directive Principles, the duties cannot be enforced in a court. They have not been empty for that reason. Courts have drawn on them in reading laws -- on protecting forests, for instance -- and they set out what the Constitution expects of citizens, not only what it promises them.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1950 में अपनाया गया संविधान नागरिकों के अधिकार बताता था पर उनके कर्तव्यों के बारे में कम कहता था। 1976 में स्वर्ण सिंह समिति की सिफ़ारिश पर बयालीसवें संशोधन ने भाग IV-क जोड़ा, जिसमें मौलिक कर्तव्यों की एक सूची थी: उनमें संविधान का पालन करना और राष्ट्रध्वज व राष्ट्रगान का सम्मान करना, भारत के सभी लोगों में सद्भाव बढ़ाना, प्राकृतिक पर्यावरण की रक्षा करना और वैज्ञानिक दृष्टिकोण विकसित करना शामिल हैं। ग्यारहवाँ, छह से चौदह वर्ष के बच्चों को शिक्षा के अवसर देने का माता-पिता का कर्तव्य, 2002 में जोड़ा गया। नीति निदेशक तत्त्वों की तरह, ये कर्तव्य न्यायालय में लागू नहीं कराए जा सकते। इस कारण वे खोखले नहीं रहे। न्यायालयों ने क़ानूनों की व्याख्या में उनका सहारा लिया है -- उदाहरण के लिए, वनों की रक्षा पर -- और वे बताते हैं कि संविधान नागरिकों से क्या अपेक्षा करता है, केवल यह नहीं कि वह उन्हें क्या वचन देता है।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s07", "passage_group": "csat-l4-s07-p04", "csat_order": 29}'::jsonb,'[{"id": "a", "body": "Though unenforceable, the duties guide courts and say what is expected of citizens.", "body_hi": "अप्रवर्तनीय होकर भी कर्तव्य न्यायालयों को दिशा देते और नागरिकों से अपेक्षा बताते हैं।", "isCorrect": true}, {"id": "b", "body": "Citizens who neglect a Fundamental Duty can be punished by any court in the country.", "body_hi": "मौलिक कर्तव्य की उपेक्षा करने वाले नागरिकों को देश का कोई भी न्यायालय दंड दे सकता है।", "isCorrect": false}, {"id": "c", "body": "The Fundamental Duties have no meaning at all, since no court can enforce them.", "body_hi": "मौलिक कर्तव्यों का कोई अर्थ नहीं, क्योंकि कोई न्यायालय उन्हें लागू नहीं करा सकता।", "isCorrect": false}, {"id": "d", "body": "The Fundamental Duties were part of the Constitution as it was adopted in 1950.", "body_hi": "मौलिक कर्तव्य 1950 में अपनाए गए संविधान का भाग थे।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage explains when and why the Fundamental Duties were added and argues that, though not enforceable in court, they matter: courts draw on them, and they state what the Constitution expects of citizens. It says the duties cannot be enforced in court, so they are not penalties; it says they have not been empty, the opposite of meaningless; and it says they were added in 1976, not in 1950.','परिच्छेद बताता है कि मौलिक कर्तव्य कब और क्यों जोड़े गए और तर्क देता है कि, न्यायालय में लागू न कराए जा सकने पर भी, वे मायने रखते हैं: न्यायालय उनका सहारा लेते हैं, और वे बताते हैं कि संविधान नागरिकों से क्या अपेक्षा करता है। वह कहता है कि कर्तव्य न्यायालय में लागू नहीं कराए जा सकते, इसलिए वे दंड नहीं; वह कहता है कि वे खोखले नहीं रहे, जो अर्थहीन होने का उलटा है; और वह कहता है कि वे 1976 में जोड़े गए, 1950 में नहीं।','csat-l4-s07-rc-p04-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
The Constitution as adopted in 1950 listed citizens'' rights but said little about their duties. In 1976, on the recommendation of the Swaran Singh Committee, the Forty-second Amendment added Part IV-A, with a list of Fundamental Duties: among them, to abide by the Constitution and respect the national flag and anthem, to promote harmony among all the people of India, to protect the natural environment and to develop a scientific temper. An eleventh, the duty of parents to provide opportunities for education to their children aged six to fourteen, was added in 2002. Like the Directive Principles, the duties cannot be enforced in a court. They have not been empty for that reason. Courts have drawn on them in reading laws -- on protecting forests, for instance -- and they set out what the Constitution expects of citizens, not only what it promises them.

According to the passage, which duty was added to the list in 2002?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1950 में अपनाया गया संविधान नागरिकों के अधिकार बताता था पर उनके कर्तव्यों के बारे में कम कहता था। 1976 में स्वर्ण सिंह समिति की सिफ़ारिश पर बयालीसवें संशोधन ने भाग IV-क जोड़ा, जिसमें मौलिक कर्तव्यों की एक सूची थी: उनमें संविधान का पालन करना और राष्ट्रध्वज व राष्ट्रगान का सम्मान करना, भारत के सभी लोगों में सद्भाव बढ़ाना, प्राकृतिक पर्यावरण की रक्षा करना और वैज्ञानिक दृष्टिकोण विकसित करना शामिल हैं। ग्यारहवाँ, छह से चौदह वर्ष के बच्चों को शिक्षा के अवसर देने का माता-पिता का कर्तव्य, 2002 में जोड़ा गया। नीति निदेशक तत्त्वों की तरह, ये कर्तव्य न्यायालय में लागू नहीं कराए जा सकते। इस कारण वे खोखले नहीं रहे। न्यायालयों ने क़ानूनों की व्याख्या में उनका सहारा लिया है -- उदाहरण के लिए, वनों की रक्षा पर -- और वे बताते हैं कि संविधान नागरिकों से क्या अपेक्षा करता है, केवल यह नहीं कि वह उन्हें क्या वचन देता है।

परिच्छेद के अनुसार, 2002 में सूची में कौन-सा कर्तव्य जोड़ा गया?','{"craft": "precision", "csat_set": "csat-l4-s07", "passage_group": "csat-l4-s07-p04", "csat_order": 30}'::jsonb,'[{"id": "a", "body": "To respect the national flag and the national anthem", "body_hi": "राष्ट्रध्वज और राष्ट्रगान का सम्मान करना", "isCorrect": false}, {"id": "b", "body": "To protect the natural environment, forests and wildlife", "body_hi": "वनों और वन्यजीवों सहित प्राकृतिक पर्यावरण की रक्षा करना", "isCorrect": false}, {"id": "c", "body": "To develop a scientific temper and the spirit of inquiry", "body_hi": "वैज्ञानिक दृष्टिकोण और खोज की भावना विकसित करना", "isCorrect": false}, {"id": "d", "body": "Parents'' duty to see children aged 6 to 14 educated", "body_hi": "6-14 वर्ष के बच्चों की शिक्षा का माता-पिता का कर्तव्य", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage says the eleventh duty, added in 2002, is that of parents to provide opportunities for education to their children aged six to fourteen. Respecting the flag and anthem, protecting the environment and developing a scientific temper are among the duties added in 1976.','परिच्छेद कहता है कि 2002 में जोड़ा गया ग्यारहवाँ कर्तव्य छह से चौदह वर्ष के बच्चों को शिक्षा के अवसर देने का माता-पिता का कर्तव्य है। ध्वज और राष्ट्रगान का सम्मान, पर्यावरण की रक्षा और वैज्ञानिक दृष्टिकोण का विकास 1976 में जोड़े गए कर्तव्यों में हैं।','csat-l4-s07-rc-p04-the-duty-added-in-2002','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
